AVGLENGTHWDIAM = 1   // if 1, merge based on avg length, weighted by diam 
AVGLENGTHWSURF = 0   // if 1, merge based on avg length, weighted by area 

AREABYLONG = 0      // if 1, rescale the length before merging 



