K(:,:,1) = [0, k0_c1_o1, 0; k0_o1_c1, 0, k0_c2_c1; 0, k0_c1_c2, 0]; % the k0
K(:,:,2) = [0, k1_c1_o1, 0; k1_o1_c1, 0, k1_c2_c1; 0, k1_c1_c2, 0]; % the k1

